css:
@keyframes fire {
  0% {
    bottom: 0px;
    opacity: 0;
  }
  9% {
    opacity: 1;
  }
  10% {
    bottom: 180px;
    opacity: 0;
  }
  11% {
    bottom: 0px;
  }

  20% {
    bottom: 0px;
    opacity: 0;
  }
  28% {
    opacity: 1;
  }
  30% {
    bottom: 180px;
    opacity: 1;
  }
  31% {
    opacity: 0;
  }
  40% {
    bottom: 0;
    opacity: 0;
  }
  50% {
    opacity: 1;
    bottom: 180px;
  }
  51% {
    opacity: 0;
  }
  60% {
    bottom: 0;
    opacity: 0;
  }
  70% {
    opacity: 1;
    bottom: 180px;
  }
  71% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}
@keyframes crawl-to-bottom {
  0% {
    transform: rotate(183deg) translateX(50%);
  }
  50% {
    transform: rotate(177deg) translateX(50%);
  }
  100% {
    transform: rotate(183deg) translateX(50%);
  }
}
@keyframes crawl-to-top {
  0% {
    transform: rotate(3deg) translateX(-50%);
  }
  50% {
    transform: rotate(-3deg) translateX(-50%);
  }
  100% {
    transform: rotate(3deg) translateX(-50%);
  }
}
@keyframes crawl-to-left {
  0% {
    transform: translateY(-50%) rotate(-93deg);
  }
  50% {
    transform: translateY(-50%) rotate(-87deg);
  }
  100% {
    transform: translateY(-50%) rotate(-93deg);
  }
}
@keyframes crawl-to-right {
  0% {
    transform: translateY(-50%) rotate(93deg);
  }
  50% {
    transform: translateY(-50%) rotate(87deg);
  }
  100% {
    transform: translateY(-50%) rotate(93deg);
  }
}

.uic {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  height: 400px;
  width: 400px;
}
.ship {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  height: 96px;
  width: 96px;
  animation: rotate-ship 10s linear infinite;
}
.bullet {
  position: absolute;
  bottom: 150px;
  left: 50%;
  transform: translate(-50%);
  height: 30px;
  width: 5px;
  background-color: aqua;
  z-index: -1;
  opacity: 0;
  animation: fire 10s linear infinite;
}

.bug {
  position: absolute;
}

.bug-walk {
  animation: walk 10s linear infinite;
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%);
}
.bug-walk-1 {
  animation: walk-1 10s linear infinite;
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%);
  opacity: 1;
}

.bug-1 {
  animation: crawl-to-bottom 2ms ease infinite;
  z-index: 3;
}

.bug-walk-2 {
  animation: walk-2 10s linear 1s infinite;
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translate(-50%);
  opacity: 0;
}

.bug-2 {
  animation: crawl-to-top 2ms ease 1s infinite;
  z-index: 3;
}

.bug-walk-3 {
  animation: walk-3 10s linear 2s infinite;
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  opacity: 0;
}

.bug-3 {
  animation: crawl-to-left 2ms ease 2s infinite;
  z-index: 3;
}

.bug-walk-4 {
  animation: walk-4 10s linear 3s infinite;
  position: absolute;
  top: 50%;
  left: -18%;
  transform: translateY(-50%);
  opacity: 0;
}

.bug-4 {
  animation: crawl-to-right 2ms ease 2s infinite;
  z-index: 3;
}

@keyframes walk-1 {
  0% {
    transform: translateY(-150px);
    opacity: 1;
  }
  10% {
    transform: translateY(0px);
    opacity: 1;
  }
  11% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}

@keyframes walk-2 {
  0% {
    opacity: 0;
    transform: translateY(50px);
  }
  9% {
    opacity: 0;
    transform: translateY(50px);
  }
  10% {
    transform: translateY(50px);
    opacity: 1;
  }
  20% {
    opacity: 1;
    transform: translateY(-50px);
  }
  21% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}
@keyframes walk-3 {
  0% {
    opacity: 0;
  }
  10% {
    opacity: 0;
    transform: translateX(50px);
  }
  19% {
    opacity: 0;
    transform: translateX(50px);
  }
  20% {
    transform: translateX(50px);
    opacity: 1;
  }
  30% {
    opacity: 1;
    transform: translateX(-50px);
  }
  31% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}
@keyframes walk-4 {
  0% {
    opacity: 0;
  }
  20% {
    opacity: 0;
    transform: translateX(-50px);
  }
  29% {
    opacity: 0;
    transform: translateX(-50px);
  }
  30% {
    transform: translateX(-50px);
    opacity: 1;
  }
  40% {
    opacity: 1;
    transform: translateX(50px);
  }
  41% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}

@keyframes rotate-ship {
  0% {
    transform: translate(-50%, -50%) rotate(0deg);
  }

  10% {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  20% {
    transform: translate(-50%, -50%) rotate(180deg);
  }
  30% {
    transform: translate(-50%, -50%) rotate(180deg);
  }
  40% {
    transform: translate(-50%, -50%) rotate(90deg);
  }
  50% {
    transform: translate(-50%, -50%) rotate(90deg);
  }
  60% {
    transform: translate(-50%, -50%) rotate(270deg);
  }
  70% {
    transform: translate(-50%, -50%) rotate(270deg);
  }
  100% {
    transform: translate(-50%, -50%) rotate(1440deg);
  }
}
